import{_ as a,o,c as e,ag as d}from"./chunks/framework.B5ULsuav.js";const c=JSON.parse('{"title":"道","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-道.md","filePath":"50-概念资料/dict-道.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-道.md"};function i(l,t,h,u,n,q){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="道" tabindex="-1">道 <a class="header-anchor" href="#道" aria-label="Permalink to &quot;道&quot;">​</a></h1><blockquote><p>传统：道家 | 佛家对应：实相/真如 | 儒家对应：天</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;道&quot;就是<strong>宇宙万物的总规律</strong>。不是高高在上的人格神，而是渗透在万事万物中的运行法则。了空居士用现代语言翻译：&quot;道&quot;就是<strong>宇宙统一场</strong>——万物最底层那个统一的能量场，也就是佛家说的&quot;实相&quot;、&quot;佛性&quot;。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;道无处不在。大到宇宙星辰，小到一草一木，都在道中。你不需要去远方找道，就在你眼前。&quot;</p></blockquote><blockquote><p>&quot;这个&#39;实相&#39;就是&#39;宇宙统一场&#39;，古人所说的&#39;天&#39;、&#39;道&#39;、&#39;实相&#39;。&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/论坛语录-宇宙统一场">论坛语录-宇宙统一场</a></p></blockquote><blockquote><p>&quot;人法地，地法天，天法道，道法自然——人效法地，地效法天，天效法道，道效法它自己的样子。一切都是自然而然。&quot;</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>道是神秘不可知的</td><td>道就在日常中，吃饭穿衣、待人接物都在道中</td></tr><tr><td>道是宗教概念</td><td>道是宇宙运行规律，可以用现代&quot;场&quot;理论来理解</td></tr><tr><td>得道了就超脱世俗了</td><td>得道的人正常吃饭睡觉，只是心里不挂碍</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>侧重</th></tr></thead><tbody><tr><td>道家</td><td>道</td><td>宇宙运行的总规律，道法自然</td></tr><tr><td>佛家</td><td>实相/真如/佛性</td><td>万物本体的空性</td></tr><tr><td>儒家</td><td>天</td><td>道德秩序的来源</td></tr><tr><td>现代</td><td>宇宙统一场</td><td>能量的统一性</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-自然">dict-自然</a> — 道法自然，自然是道的运作方式</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-无为">dict-无为</a> — 无为是按照道的规律行事</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-天人合一">model-天人合一</a> — 道是万物一体的本体论基础</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>&quot;观天之道，执天之行&quot;——观察自然规律，按规律做事，就是&quot;合道&quot;。日常中问自己&quot;这件事的客观规律是什么？&quot;而不是&quot;我想要什么？&quot;</p>',18)])])}const b=a(r,[["render",i]]);export{c as __pageData,b as default};
